	if (gBattleTypeFlags & BATTLE_TYPE_TRAINER || IsRaidBattle() || keepConsumables)
	{
		for (int i = 0; i < PARTY_SIZE; ++i)
		{
			if (gBattleTypeFlags & BATTLE_TYPE_FRONTIER
			||  keepConsumables
